using GraphApi.Models.JNT.Juntas;namespace GraphApi.Services.JNT.Juntas{    /// <summary>    /// Define las operaciones de negocio y persistencia para Juntas.    /// </summary>    public interface IJuntasService    {        /// <summary>        /// Obtiene la lista de Juntas con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadJuntas>> GetJuntas(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de Juntas con filtros opcionales.        /// </summary>        /// <param name="juntaID">Filtro opcional para JuntaID.</param>        /// <param name="titulo">Filtro opcional para Titulo.</param>        /// <param name="descripcion">Filtro opcional para Descripcion.</param>        /// <param name="fechaProgramada">Filtro opcional para FechaProgramada.</param>        /// <param name="ubicacion">Filtro opcional para Ubicacion.</param>        /// <param name="bActivo">Filtro opcional para bActivo.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetJuntasDynamic(            int? juntaID,            string? titulo,            string? descripcion,            DateTime? fechaProgramada,            string? ubicacion,            bool? bActivo,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo Junta.        /// </summary>        /// <param name="objInput">Datos para crear el Junta.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadJuntas> CreateJuntas(            clCreateJuntas objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un Junta.        /// </summary>        /// <param name="objInput">Datos para actualizar el Junta, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadJuntas?> UpdateJuntas(            clUpdateJuntas objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un Junta por su ID.        /// </summary>        /// <param name="nJuntasID">ID del Junta a eliminar.</param>        Task<bool> DeleteJuntas(int nJuntasID);    }}